<script setup lang="ts">
import { exportQualityFinal, exportQualityWorkbook, generateQualityFinal, getJuniorQualityClasses, getQualityClassStudents, getQualityConfig, getQualityFinal, getQualityMissingReviews, getStudentQuality, getStudentQualitySummary, importQualityWorkbook, lockQualityFinal, saveStudentQualitySemester, updateQualityFinalLevel, updateQualityFinalRatios, updateQualityMissingReview } from "@/api/quality";
import type { UploadFile, UploadInstance } from "element-plus";
type StudentRow = { studentId: number; code: string; name: string; completedSemesters: number; inFinalScope?: number; pendingMissingCount?: number };
type MissingReview = { studentId: number; code: string; name: string; semester: string; status: "PENDING" | "CONFIRMED_MISSING" | "CONFIRMED_TRANSFER_IN"; missingDimensions: string; remark?: string };
const config = ref<any>({ dimensions: [], semesters: [], entryLevels: ["A", "B", "C", "N/A"] });
const classes = ref<any[]>([]); const students = ref<StudentRow[]>([]); const clazzId = ref<number>(); const selectedStudent = ref<StudentRow>(); const records = ref<any[]>([]); const summary = ref<any>({ dimensionTotals: {} }); const matrix = reactive<Record<string, Record<string, string>>>({});
const loading = ref(false); const importDialog = ref(false); const importFile = ref<File>(); const uploadRef = ref<UploadInstance>(); const finalRows = ref<any[]>([]); const finalState = ref<any>({ isLocked: 0, baselineStudentCount: 0, pendingReviewCount: 0, pendingStudentCount: 0, scoredStudentCount: 0, aRatio: 0.6, bRatio: 0.35, cRatio: 0.05 }); const finalDialog = ref(false); const reviewDialog = ref(false); const reviewLoading = ref(false); const missingReviews = ref<MissingReview[]>([]); const ratioSaving = ref(false);
const pendingReviews = computed(() => missingReviews.value.filter((item) => item.status === "PENDING"));
const baselineCount = computed(() => Number(finalState.value.baselineStudentCount ?? 0));
const pendingStudentCount = computed(() => Number(finalState.value.pendingStudentCount ?? new Set(pendingReviews.value.map((item) => item.studentId)).size));
const scoredStudentCount = computed(() => Number(finalState.value.scoredStudentCount ?? 0));
function resetMatrix() { Object.keys(matrix).forEach((key) => delete matrix[key]); for (const semester of config.value.semesters ?? []) { matrix[semester] = {}; for (const dimension of config.value.dimensions ?? []) matrix[semester][dimension] = "N/A"; } }
function semesterLabel(value: string) { const labels: Record<string, string> = { junior_1_1: "初一上", junior_1_2: "初一下", junior_2_1: "初二上", junior_2_2: "初二下", junior_3_1: "初三上", junior_3_2: "初三下" }; return labels[value] ?? value; }
function savedLevel(semester: string, dimension: string) { return records.value.find((record) => record.semester === semester && record.dimension === dimension)?.level ?? "N/A"; }
function statusLabel(status: string) { return status === "PENDING" ? "待确认" : status === "CONFIRMED_TRANSFER_IN" ? "已确认转入" : "已确认缺失"; }
function statusType(status: string) { return status === "PENDING" ? "warning" : status === "CONFIRMED_TRANSFER_IN" ? "success" : "info"; }
function classLabel(item: any) { return `${item.gradeName ?? ""} ${item.name ?? ""}`.trim(); }
function hideInternalBaselineLabels() { const replacements: Record<string, string> = { "九上基准人数": "最终统计人数", "九上基准": "最终统计范围", "九上工作表": "最后一个学期名单", "以“九上”工作表为准": "按最后一个学期名单确定", "以九上名单锁定最终人数": "按最后一个学期名单确定最终人数" }; const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); const nodes: Text[] = []; let node: Node | null; while ((node = walker.nextNode())) nodes.push(node as Text); nodes.forEach((textNode) => { let value = textNode.nodeValue ?? ""; Object.entries(replacements).forEach(([from, to]) => { value = value.replaceAll(from, to); }); textNode.nodeValue = value; }); }
async function loadClasses() { const { data } = await getJuniorQualityClasses(); classes.value = data ?? []; if (!clazzId.value && classes.value.length) { clazzId.value = classes.value[0].id; await loadStudents(); } }
async function loadStudents() { if (!clazzId.value) return; selectedStudent.value = undefined; records.value = []; summary.value = { dimensionTotals: {} }; const { data } = await getQualityClassStudents(clazzId.value); students.value = data ?? []; }
async function loadMissingReviews() { if (!clazzId.value) return; const { data } = await getQualityMissingReviews(clazzId.value); missingReviews.value = data ?? []; }
async function loadFinal() { if (!clazzId.value) return; const [{ data }, missingResponse] = await Promise.all([getQualityFinal(clazzId.value), getQualityMissingReviews(clazzId.value)]); finalRows.value = data?.rows ?? []; finalState.value = data?.state ? { ...data.state, ...data } : { ...finalState.value, ...data }; missingReviews.value = missingResponse.data ?? []; }
async function selectStudent(row: StudentRow | null) { if (!row) return; selectedStudent.value = row; resetMatrix(); const [recordResponse, summaryResponse] = await Promise.all([getStudentQuality(row.studentId), getStudentQualitySummary(row.studentId)]); records.value = recordResponse.data ?? []; summary.value = summaryResponse.data ?? { dimensionTotals: {} }; records.value.forEach((record) => { if (matrix[record.semester]) matrix[record.semester][record.dimension] = record.level ?? "N/A"; }); }
async function saveAll() { if (!selectedStudent.value) return ElMessage.warning("请先选择学生"); loading.value = true; try { for (const semester of config.value.semesters) await saveStudentQualitySemester(selectedStudent.value.studentId, semester, matrix[semester]); ElMessage.success("综合素质评价已保存"); await selectStudent(selectedStudent.value); await loadStudents(); await loadMissingReviews(); } finally { loading.value = false; } }
function chooseFile(file: UploadFile) { importFile.value = file.raw; }
async function doImport() { if (!clazzId.value || !importFile.value) return ElMessage.warning("请选择要导入的 Excel 文件"); const { data } = await importQualityWorkbook(clazzId.value, importFile.value); const issueText = data.issues?.length ? `，${data.issues.length} 条未匹配/校验提示` : ""; ElMessage.success(`导入完成：匹配 ${data.matchedRows} 行，最终统计范围 ${data.baselineStudentCount ?? 0} 人${issueText}`); if (data.issues?.length) await ElMessageBox.alert(data.issues.slice(0, 100).join("\n"), "导入提示", { confirmButtonText: "我已知晓" }); importDialog.value = false; importFile.value = undefined; uploadRef.value?.clearFiles(); await loadStudents(); await loadFinal(); }
async function generateFinal() { if (!clazzId.value) return; const { data } = await generateQualityFinal(clazzId.value); await loadFinal(); finalDialog.value = true; if (Number(data?.pendingReviewCount ?? finalState.value.pendingReviewCount) > 0) ElMessage.warning("仍有缺失成绩待确认，这些学生暂不生成最终等级"); else ElMessage.success("最终评定已重新计算"); }
async function toggleFinalLock() { if (!clazzId.value) return; const next = !Boolean(finalState.value.isLocked); await lockQualityFinal(clazzId.value, next); ElMessage.success(next ? "最终评定已锁定" : "最终评定已解锁"); await loadFinal(); }
async function openFinal() { await loadFinal(); finalDialog.value = true; }
async function saveRatios() { if (!clazzId.value) return; const aRatio = Number(finalState.value.aRatio); const bRatio = Number(finalState.value.bRatio); const cRatio = Number(finalState.value.cRatio); if ([aRatio, bRatio, cRatio].some((value) => value < 0) || Math.abs(aRatio + bRatio + cRatio - 1) > 0.0001) return ElMessage.warning("A/B/C 比例必须合计 100%"); ratioSaving.value = true; try { await updateQualityFinalRatios(clazzId.value, { aRatio, bRatio, cRatio }); await generateQualityFinal(clazzId.value); await loadFinal(); ElMessage.success("比例已保存并重新计算"); } finally { ratioSaving.value = false; } }
function exportFinal() { if (!clazzId.value) return; exportQualityFinal(clazzId.value).then((response: any) => { const blob = new Blob([response.data], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "综合素质评价-正式最终结果.xlsx"; link.click(); URL.revokeObjectURL(url); }); }
async function openReview() { await loadMissingReviews(); reviewDialog.value = true; }
async function confirmReview(item: any, status: "CONFIRMED_MISSING" | "CONFIRMED_TRANSFER_IN") { if (!clazzId.value) return; reviewLoading.value = true; try { await updateQualityMissingReview(clazzId.value, item.studentId, item.semester, { status, remark: item.remark }); ElMessage.success(status === "CONFIRMED_TRANSFER_IN" ? "已确认该生为转入，跳过该学期" : "已确认该学期成绩缺失"); await loadFinal(); await loadStudents(); } finally { reviewLoading.value = false; } }
async function resetReview(item: any) { if (!clazzId.value) return; await updateQualityMissingReview(clazzId.value, item.studentId, item.semester, { status: "PENDING", remark: item.remark }); await loadFinal(); await loadStudents(); }
function changeFinalLevel(row: any, level: string) { if (!clazzId.value || finalState.value.isLocked) return; updateQualityFinalLevel(clazzId.value, row.studentId, row.dimension, level).then(() => ElMessage.success("最终等级已调整")); }
function doExport() { if (!clazzId.value) return ElMessage.warning("请先选择班级"); exportQualityWorkbook(clazzId.value).then((response: any) => { const blob = new Blob([response.data], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "初中综合素质评价-班级名单.xlsx"; link.click(); URL.revokeObjectURL(url); }); }
async function changeClass() { await loadStudents(); await loadFinal(); }
onMounted(async () => { const { data } = await getQualityConfig(); config.value = data; resetMatrix(); await loadClasses(); await loadFinal(); await nextTick(); hideInternalBaselineLabels(); });
watch([importDialog, finalDialog], async () => { await nextTick(); hideInternalBaselineLabels(); });
</script>
<template>
  <div class="app-container quality-page">
    <div class="page-heading"><div><div class="eyebrow">QUALITY EVALUATION</div><h2>初中综合素质评价</h2><p>按班级维护六学期评价，最终人数以“九上”工作表为准。</p></div><el-tag effect="plain" type="success"><i-ep-lock /> 本地数据</el-tag></div>
    <el-card shadow="never" class="toolbar-card"><div class="toolbar"><el-form inline><el-form-item label="评价班级"><el-select v-model="clazzId" class="class-select" placeholder="请选择班级" @change="changeClass"><el-option v-for="item in classes" :key="item.id" :label="classLabel(item)" :value="item.id" /></el-select></el-form-item></el-form><div class="toolbar-actions"><el-button type="primary" @click="importDialog = true"><i-ep-upload />导入评价表</el-button><el-button @click="doExport"><i-ep-download />导出</el-button><el-button type="warning" plain @click="generateFinal"><i-ep-refresh />重新计算</el-button><el-button plain @click="openFinal">查看最终评定</el-button></div></div><div class="toolbar-note"><i-ep-info-filled /> 导入后系统会以九上名单锁定最终人数；转入学生缺少的学期必须先完成确认。</div></el-card>
    <div class="metric-grid"><div class="metric-card metric-primary"><span>九上基准人数</span><strong>{{ baselineCount || "—" }}</strong><small>最终统计范围</small></div><div class="metric-card"><span>已生成等级</span><strong>{{ scoredStudentCount || "—" }}</strong><small>已参与最终排名</small></div><div class="metric-card metric-warning"><span>待确认缺失</span><strong>{{ pendingStudentCount }}</strong><small>确认后才会计入</small></div><div class="metric-card"><span>评价记录</span><strong>{{ students.length }}</strong><small>当前班级学生</small></div></div>
    <el-card shadow="never" class="workspace-card"><template #header><div class="section-header"><div><span class="section-title">班级评价明细</span><span class="section-subtitle">选择学生维护每学期五个维度</span></div><el-button v-if="pendingReviews.length" type="warning" plain @click="openReview"><i-ep-warning />处理 {{ pendingReviews.length }} 条缺失</el-button></div></template><el-row :gutter="20"><el-col :span="8"><div class="student-panel"><div class="panel-caption"><span>学生名单</span><el-tag size="small" effect="plain">{{ students.length }} 人</el-tag></div><el-table :data="students" row-key="studentId" highlight-current-row height="584" @current-change="selectStudent"><el-table-column type="index" width="48" label="#" /><el-table-column prop="code" label="学号" width="118" /><el-table-column prop="name" label="姓名" min-width="88" /><el-table-column label="状态" width="96"><template #default="scope"><el-tag v-if="scope.row.pendingMissingCount" type="warning" size="small">待确认</el-tag><el-tag v-else-if="scope.row.inFinalScope" type="success" size="small">九上基准</el-tag><span v-else class="muted">—</span></template></el-table-column><el-table-column prop="completedSemesters" label="已录学期" width="88" align="center" /></el-table><el-empty v-if="!students.length" description="该班级暂无学生" /></div></el-col><el-col :span="16"><div class="detail-panel"><el-empty v-if="!selectedStudent" description="请从左侧选择学生" :image-size="96" /><template v-else><div class="student-title"><div><span class="student-name">{{ selectedStudent.name }}</span><span class="student-code">{{ selectedStudent.code }}</span><el-tag v-if="selectedStudent.pendingMissingCount" type="warning" size="small">有缺失待确认</el-tag></div><el-button type="primary" :loading="loading" @click="saveAll">保存全部学期评价</el-button></div><el-table :data="config.semesters.map((s: string) => ({ semester: s }))" border><el-table-column prop="semester" label="学期" width="130"><template #default="scope">{{ semesterLabel(scope.row.semester) }}</template></el-table-column><el-table-column v-for="dimension in config.dimensions" :key="dimension" :label="dimension" min-width="110"><template #default="scope"><el-select v-model="matrix[scope.row.semester][dimension]" size="small"><el-option v-for="level in config.entryLevels" :key="level" :label="level" :value="level" /></el-select></template></el-table-column></el-table><div class="summary-heading">五维累计分</div><div class="score-grid"><div v-for="dimension in config.dimensions" :key="dimension" class="score-item"><span>{{ dimension }}</span><strong>{{ Number(summary.dimensionTotals?.[dimension] ?? 0).toFixed(2) }}</strong></div></div><div class="summary-heading records-heading">当前已保存记录</div><el-table :data="config.semesters.map((s: string) => ({ semester: s }))" border size="small" class="records"><el-table-column prop="semester" label="学期" width="130"><template #default="scope">{{ semesterLabel(scope.row.semester) }}</template></el-table-column><el-table-column v-for="dimension in config.dimensions" :key="dimension" :label="dimension" min-width="110"><template #default="scope"><el-tag size="small" :type="savedLevel(scope.row.semester, dimension) === 'N/A' ? 'warning' : 'success'">{{ savedLevel(scope.row.semester, dimension) }}</el-tag></template></el-table-column></el-table></template></div></el-col></el-row></el-card>
  </div>
  <el-dialog v-model="importDialog" title="导入综合素质评价" width="560px"><div class="import-intro"><i-ep-document-checked /><div><strong>支持六个学期工作表</strong><p>至少包含“学号/考号、姓名”和五个维度列。系统优先按学号匹配，并用九上工作表确定最终人数。</p></div></div><el-upload ref="uploadRef" drag :auto-upload="false" :limit="1" accept=".xlsx,.xls" :on-change="chooseFile" :on-exceed="(files: any[]) => { uploadRef?.clearFiles(); chooseFile(files[0]); }"><i-ep-upload-filled /><div class="el-upload__text">将文件拖到此处，或<em>点击上传</em></div></el-upload><template #footer><el-button @click="importDialog = false">取消</el-button><el-button type="primary" @click="doImport">开始导入</el-button></template></el-dialog>
  <el-dialog v-model="finalDialog" title="最终评定结果" width="1120px"><div class="final-summary"><div><span>九上基准</span><strong>{{ baselineCount }}</strong><small>人</small></div><div><span>已生成等级</span><strong>{{ scoredStudentCount }}</strong><small>人</small></div><div class="warning"><span>待确认缺失</span><strong>{{ pendingStudentCount }}</strong><small>人</small></div><div class="final-state"><span>状态</span><el-tag :type="finalState.isLocked ? 'success' : 'warning'">{{ finalState.isLocked ? "已锁定" : "未锁定" }}</el-tag><el-button size="small" @click="toggleFinalLock">{{ finalState.isLocked ? "解锁" : "锁定结果" }}</el-button></div></div><div class="ratio-panel"><div><strong>等级比例</strong><span>自动等级按累计分排名计算，老师确认后锁定。</span></div><div class="ratio-fields"><label>A <el-input-number v-model="finalState.aRatio" :min="0" :max="1" :step="0.05" :precision="2" size="small" /></label><label>B <el-input-number v-model="finalState.bRatio" :min="0" :max="1" :step="0.05" :precision="2" size="small" /></label><label>C <el-input-number v-model="finalState.cRatio" :min="0" :max="1" :step="0.05" :precision="2" size="small" /></label><el-button size="small" type="primary" plain :loading="ratioSaving" :disabled="Boolean(finalState.isLocked)" @click="saveRatios">保存比例并重算</el-button></div></div><el-alert v-if="pendingReviews.length" type="warning" show-icon :closable="false" class="review-alert" title="有学生存在未确认的缺失成绩，暂不生成其最终等级"><template #default><el-button link type="warning" @click="openReview">立即处理缺失确认</el-button></template></el-alert><div class="final-actions"><span>老师逐项确认最终等级后，请点击“锁定结果”再导出正式表。</span><el-button type="success" plain :disabled="!finalState.isLocked || pendingReviews.length > 0" @click="exportFinal"><i-ep-download />导出正式最终结果</el-button></div><el-table :data="finalRows" border max-height="480"><el-table-column prop="code" label="学号" width="124" /><el-table-column prop="name" label="姓名" width="96" /><el-table-column prop="dimension" label="维度" width="118" /><el-table-column prop="cumulativeScore" label="累计分" width="90" /><el-table-column prop="classRank" label="班级名次" width="92" /><el-table-column prop="availableTerms" label="有效学期" width="88" /><el-table-column label="数据状态" width="100"><template #default="scope"><el-tag v-if="scope.row.containsNa" type="warning" size="small">含缺失</el-tag><el-tag v-else type="success" size="small">完整</el-tag></template></el-table-column><el-table-column prop="automaticLevel" label="自动等级" width="90" /><el-table-column label="最终等级" width="112"><template #default="scope"><el-select v-model="scope.row.finalLevel" size="small" :disabled="Boolean(finalState.isLocked)" @change="changeFinalLevel(scope.row, scope.row.finalLevel)"><el-option label="A" value="A" /><el-option label="B" value="B" /><el-option label="C" value="C" /></el-select></template></el-table-column></el-table></el-dialog>
  <el-dialog v-model="reviewDialog" title="缺失成绩确认" width="980px"><div class="review-head"><div><strong>先确认，再生成等级</strong><p>待确认的学生不会按缺失数据直接获得正常等级。若为中途转入，可确认转入；若确实缺少材料，可确认缺失。</p></div><el-tag type="warning">待确认 {{ pendingReviews.length }} 条</el-tag></div><el-table :data="missingReviews" border max-height="500" v-loading="reviewLoading"><el-table-column prop="code" label="学号" width="124" /><el-table-column prop="name" label="姓名" width="96" /><el-table-column prop="semester" label="缺失学期" width="144"><template #default="scope">{{ semesterLabel(scope.row.semester) }}</template></el-table-column><el-table-column prop="missingDimensions" label="缺失维度" min-width="210" /><el-table-column label="状态" width="112"><template #default="scope"><el-tag :type="statusType(scope.row.status)" size="small">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="250" fixed="right"><template #default="scope"><template v-if="scope.row.status === 'PENDING'"><el-button size="small" type="success" plain @click="confirmReview(scope.row, 'CONFIRMED_TRANSFER_IN')">确认转入</el-button><el-button size="small" type="warning" plain @click="confirmReview(scope.row, 'CONFIRMED_MISSING')">确认缺失</el-button></template><el-button v-else size="small" link @click="resetReview(scope.row)">恢复待确认</el-button></template></el-table-column><template #empty><el-empty description="没有需要确认的缺失成绩" /></template></el-table></el-dialog>
</template>
<style scoped>
